mapper.sql:
WHERE 1=1

  AND (UPPER(NVL(T1.PLAN_ID,'')) LIKE '%'||UPPER(#{keyword})||'%'
    OR UPPER(NVL(T1.TARGET_ID,'')) LIKE '%'||UPPER(#{keyword})||'%'
    OR UPPER(NVL(T1.GAP_REMARK,'')) LIKE '%'||UPPER(#{keyword})||'%')

AND T1.WAVE_ID = #{waveId}
AND T1.STRATEGY_7R_CD = #{strategy7rCd}
AND T1.TARGET_TYPE_CD = #{targetTypeCd}
AND T1.DIFFICULTY_CD = #{difficultyCd}

mapper.select:
SELECT * FROM (
  SELECT a.*, ROWNUM rnum FROM (
    SELECT T1.PLAN_ID AS PLAN_ID, T1.WAVE_ID AS WAVE_ID, T1.WAVE_NAME AS WAVE_NAME,
           T1.TARGET_TYPE_CD AS TARGET_TYPE_CD, T1.TARGET_ID AS TARGET_ID,
           T1.STRATEGY_7R_CD AS STRATEGY_7R_CD,
           T1.CURRENT_PLATFORM_CD AS CURRENT_PLATFORM_CD,
           T1.TARGET_PLATFORM_CD AS TARGET_PLATFORM_CD,
           T1.DIFFICULTY_CD AS DIFFICULTY_CD, T1.STATUS_CD AS STATUS_CD,
           T1.GAP_REMARK AS GAP_REMARK
      FROM V_IF_MIGRATION_MAPPING T1

     ORDER BY T1.DIFFICULTY_CD DESC, T1.WAVE_ID, T1.PLAN_ID
  ) a WHERE ROWNUM <= #{offset} + #{pageSize}
) WHERE rnum > #{offset}
